insert into public.ai_knowledge (kind, area, country_code, topic, title, summary, source_name, source_url, license, lang, status) values
('management','operacion','PE','licencia_funcionamiento_municipal_itse',$k$Perú: licencia de funcionamiento municipal e ITSE$k$,$k$La licencia de funcionamiento la otorga la municipalidad del distrito donde está el local, bajo la Ley 28976 (TUO aprobado por DS 163-2020-PCM). La ley fija un procedimiento único y requisitos máximos: según la guía del MEF/PCM, las municipalidades no deben exigir requisitos adicionales a los previstos en el artículo 7. La municipalidad evalúa zonificación y compatibilidad de uso y las condiciones de seguridad de la edificación mediante la Inspección Técnica de Seguridad en Edificaciones (ITSE). Para riesgo bajo o medio se presenta una declaración jurada de cumplimiento de condiciones de seguridad y la inspección se hace después de otorgada la licencia; para riesgo alto o muy alto la inspección es previa. El certificado ITSE tiene vigencia de 2 años (DS 002-2018-PCM). En un ejemplo municipal publicado en gob.pe, la licencia tiene vigencia indeterminada y se mantiene renovando el ITSE. Costos, plazos y formularios varían por municipalidad (TUPA de cada una): confirmar en la municipalidad y en gob.pe. Dónde confirmar: gob.pe (trámite de licencia de funcionamiento), portal de la municipalidad distrital, El Peruano para el texto de la norma.$k$,'Texto Único Ordenado Ley 28976 (El Peruano) y guía MEF/PCM; gob.pe','https://diariooficial.elperuano.pe/Normas/obtenerDocumento?idNorma=30',$k$Material informativo de fuentes oficiales peruanas; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','operacion','CO','establecimiento_comercio_uso_suelo_bomberos_ica',$k$Colombia: permisos locales para abrir un establecimiento (uso de suelo, Bomberos, RIT/ICA)$k$,$k$Además de la matrícula mercantil en la Cámara de Comercio (se renueva cada año) y el RUT, un establecimiento abierto al público debe cumplir requisitos locales. La Secretaría General de la Alcaldía de Bogotá resume los del Código de Policía (Ley 1801, art. 87): respetar las normas de uso del suelo, mantener vigente la matrícula mercantil, cumplir condiciones de seguridad, sanitarias y ambientales, y desarrollar solo el objeto registrado. Documentos que menciona la Alcaldía de Bogotá: registro de Cámara de Comercio, uso del suelo (consulta en la Secretaría Distrital de Planeación, gratuita), concepto sanitario, carta de apertura y concepto técnico de Bomberos. En materia tributaria local, quien es contribuyente del impuesto de industria y comercio (ICA) se identifica con la inscripción en el RIT; según la Cámara de Comercio de Bogotá, fuera de Bogotá se consulta a la Secretaría de Hacienda del municipio si hay convenio para inscribir el RIT. El ICA se declara en el municipio donde está el establecimiento. Si se cierra el negocio, la cancelación de la matrícula no cancela el RIT: Medellín exige informar el cese ante su oficina de Industria y Comercio (plazo: confirmar en su ABECE). Bogotá cobra una sobretasa bomberil del 1 % a contribuyentes de ICA sobre cierto ingreso: umbral y vigencia, confirmar. Los requisitos varían por municipio.$k$,'Alcaldía de Bogotá; Cámara de Comercio de Bogotá; Secretaría de Hacienda de Bogotá','https://bogota.gov.co/mi-ciudad/gobierno/documentos-y-tramites-para-establecimientos-de-comercio-en-bogota',$k$Material informativo de fuentes oficiales y de cámaras de comercio colombianas; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','operacion','PY','patente_comercial_municipal_habilitacion',$k$Paraguay: patente comercial municipal y habilitación del local$k$,$k$La patente es un tributo municipal anual que pagan quienes ejercen comercio, industria o profesión con fines de lucro en el municipio. Para Asunción la rige la Ley 881 (la patente se calcula según una escala vinculada al activo comercial; en aperturas de negocio se abona por el semestre correspondiente) y para los municipios del interior la Ley 620/1976, además de las ordenanzas de cada municipalidad. Existe patente comercial y patente profesional (para profesionales, que es distinta: p. ej. la DNCP aclara que a los escribanos les corresponde la profesional). La SUACE (MIC) incluye en su flujo de constitución la patente comercial y la licencia municipal de Asunción. Pasos habituales descritos por una fuente secundaria (yo-facturo, no oficial): reunir documentos, presentar la solicitud en la municipalidad, inspección del local si corresponde, pagar la patente y retirar la habilitación. Plazos y fechas de declaración dependen de la ordenanza de cada municipio (un estudio profesional cita la Ordenanza 244/2019 de Asunción: confirmar vigencia). Montos y requisitos: confirmar en la municipalidad donde está el local.$k$,'Leyes Paraguayas (BACN) Ley 881 y Ley 620; MIC SUACE','https://www.bacn.gov.py/leyes-paraguayas/3505/ley-n-881-establece-el-regimen-tributario-y-de-otros-recursos-para-la-municipalidad-de-asuncion',$k$Material informativo de fuentes oficiales paraguayas y fuentes secundarias señaladas en el texto; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','operacion','CL','patente_municipal_requisitos_informe_sanitario',$k$Chile: patente municipal y permisos del local$k$,$k$Toda actividad lucrativa con local o establecimiento fijo requiere patente municipal, regulada por el DL 3.063 de Rentas Municipales y las ordenanzas de cada comuna; la Ley 20.494 (2011) agilizó los trámites de inicio de actividades. Tipos: comercial, industrial, profesional y de alcoholes (con ley propia, 19.925); existen modalidades para microempresa familiar. Antes de la patente se hace el inicio de actividades en el SII, con domicilio en la comuna. Requisitos frecuentes (varían por comuna): formulario municipal, documento del inmueble (escritura o contrato), declaración jurada de capital propio inicial, informe de uso de suelo/factibilidad de la Dirección de Obras Municipales, y para alimentos, salud o industria el informe sanitario favorable de la autoridad sanitaria (ChileAtiende ficha 163, trámite en línea con ClaveÚnica). Las municipalidades deben otorgar la patente definitiva o provisoria según la ley. El valor depende del capital propio y de la comuna: confirmar en la Dirección de Rentas/Patentes de la municipalidad. Algunas fuentes usadas son de empresas privadas (Nubox, CompanyHero): el detalle debe verificarse con la municipalidad.$k$,'SII (SIIEduca), ChileAtiende, Ministerio de Economía, Diario Oficial','https://www.sii.cl/siieduca/aprende-con-nosotros/inicio-de-actividades-y-formalizacion-de-un-negocio.html',$k$Material informativo de fuentes oficiales chilenas y fuentes privadas señaladas; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','operacion','AR','habilitacion_comercial_tasas_municipales',$k$Argentina: habilitación comercial municipal y tasas locales$k$,$k$La habilitación comercial es un trámite municipal (en CABA, de la Dirección General de Habilitaciones y Permisos) y los requisitos cambian según municipio, provincia y actividad. Documentación frecuente en las guías municipales: DNI o documentación societaria, constancia de inscripción en ARCA (ex AFIP), inscripción en Ingresos Brutos (provincial), contrato de alquiler o título de propiedad, planos o certificados de seguridad según el caso. En CABA conviene verificar antes que la actividad esté permitida en la dirección (herramienta Ciudad 3D); la ciudad informa que un local librado al uso no equivale a tener la habilitación, y existe habilitación exprés para locales de menos de 200 m² si se cumplen condiciones. Algunos municipios (p. ej. Tres de Febrero) ofrecen habilitación online automática. Tributos locales habituales: tasa de inspección de seguridad e higiene (TISH) y tasa de habilitación de actividades económicas (THAE), con nombres y montos propios de cada municipio. Plazos, costos y exenciones: confirmar en el municipio. Este material usa guías de municipios ejemplo, no cubre todo el país.$k$,'Gobierno de la Ciudad de Buenos Aires; guías municipales','https://buenosaires.gob.ar/tramites/como-habilitar-tu-local-comercial-en-la-ciudad',$k$Material informativo de fuentes oficiales argentinas (municipales y de CABA) y notas de prensa señaladas; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','operacion','BR','alvara_funcionamento_licencas_sanitaria_bombeiros',$k$Brasil: alvará de funcionamento y licencias complementarias$k$,$k$El alvará de funcionamento lo emite la prefeitura del municipio donde está la empresa y autoriza la actividad en un endereço determinado; verifica compatibilidad con el zoneamento y condiciones del inmueble. Según fuentes profesionales y Sebrae, según la actividad pueden exigirse además: AVCB del Corpo de Bombeiros (estadual), licencia sanitaria de la Vigilância Sanitária (alimentos, salud, estética), y licencia ambiental (actividades de impacto). Documentos que suelen pedirse: CNPJ, contrato social o CCMEI, comprobante de uso del inmueble (IPTU, contrato de locação) y certidão de zoneamento. Muchos trámites se inician por la Redesim / Junta Comercial del estado. Fuentes secundarias indican que el alvará suele renovarse cada año y que un comercio electrónico sin atención al público normalmente no necesita alvará ni AVCB: ambas afirmaciones dependen del municipio, confirmar. Esta ficha se apoya sobre todo en fuentes no gubernamentales (Asaas, Omie, Serasa, Sebrae) porque las páginas de gov.br consultadas no daban detalle. Tasas y plazos: portal de la prefeitura.$k$,'Redesim (gov.br); Sebrae; fuentes profesionales brasileñas','https://www.gov.br/empresas-e-negocios/pt-br/redesim/ajuda/licenciamento',$k$Material informativo de gov.br, Sebrae y fuentes profesionales señaladas en el texto; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','operacion','MX','licencia_funcionamiento_uso_suelo_proteccion_civil_sare',$k$México: licencia de funcionamiento municipal, uso de suelo, Protección Civil y SARE$k$,$k$La licencia de funcionamiento la expide el municipio o alcaldía y suele requerir: certificado o licencia de uso de suelo, visto bueno o dictamen de Protección Civil y, si se manejan alimentos u otros giros regulados, aviso de funcionamiento ante COFEPRIS. Para negocios de bajo riesgo existe el Sistema de Apertura Rápida de Empresas (SARE), con lineamientos publicados en gob.mx; cada municipio opera su propio módulo, catálogo de giros y manual (los manuales municipales consultados muestran, p. ej., uso de suelo para bajo riesgo hasta 300 m² en algunos casos y plazos de pocos días). Una fuente de prensa especializada menciona alta municipal en 72 horas bajo SARE: es un dato no oficial y depende del municipio. Requisitos típicos (acta constitutiva, comprobante de propiedad o arrendamiento, antecedentes del predio) cambian por municipio. Costos y plazos: confirmar en el módulo SARE o la dirección de desarrollo económico del municipio, y en gob.mx/cofepris.$k$,'gob.mx (Lineamientos SARE); manuales SARE municipales','https://www.gob.mx/cms/uploads/attachment/file/872692/LINEAMIENTOS_del_Sistema_de_Apertura_Rapida_de_Empresas__SARE__y_del_Pro....pdf',$k$Material informativo de fuentes oficiales mexicanas (federal y municipales) y prensa señalada; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','operacion','EC','patente_municipal_luae_permiso_funcionamiento',$k$Ecuador: patente municipal, LUAE y permisos de funcionamiento$k$,$k$La patente municipal es un permiso indispensable para ejercer actividades económicas y se renueva anualmente (trámite publicado por municipios en gob.ec; el requisito principal incluye RUC actualizado y permiso del Cuerpo de Bomberos, según el municipio). En Quito la LUAE (Licencia Metropolitana Única para el Ejercicio de Actividades Económicas) integra patente, inspecciones de Bomberos, ambiente, turismo, salud y rotulación; clasifica actividades en categorías (1 simplificado, 2 ordinario, 3 especial) y se tramita por emisión o renovación anual. Para solicitarla debe estar al día la patente y validarse la compatibilidad de uso de suelo (ICUS). Otros municipios usan la LUAF (Licencia Única Anual de Funcionamiento) para establecimientos turísticos, con tasa regulada por el Ministerio de Turismo. El Ministerio de Gobierno publica requisitos de permisos de funcionamiento por categoría (patente, Bomberos, RUC, ARCSA para alimentos y bebidas alcohólicas). Cada cantón tiene sus formularios y costos: confirmar en el GAD municipal y en gob.ec.$k$,'gob.ec (Registro Único de Trámites); Municipio de Quito; Ministerio de Gobierno','https://www.gob.ec/gaddmq/tramites/licencia-metropolitana-unica-ejercicio-actividades-economicas-luae',$k$Material informativo de fuentes oficiales ecuatorianas; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft'),
('management','operacion','UY','habilitacion_comercial_intendencia_bomberos_msp',$k$Uruguay: habilitación comercial de la intendencia, Bomberos y habilitación sanitaria$k$,$k$La habilitación comercial la otorga la intendencia departamental (p. ej. Montevideo, Paysandú) para el funcionamiento de locales comerciales, oficinas e industrias. En Paysandú, el portal gub.uy exige presentar formulario, documento de identidad y certificación de medidas de protección contra incendios, es decir la habilitación de la Dirección Nacional de Bomberos; para locales industriales se solicita además la habilitación ambiental (la fuente menciona DINAMA: confirmar el organismo actual). En Montevideo la documentación incluye planos, habilitación de Bomberos y, según el caso, viabilidad de uso; para locales de hasta 200 m² el trámite se realiza en el centro comunal zonal. La habilitación higiénico sanitaria (Ley 9.202) la emite el Ministerio de Salud Pública para empresas y locales comerciales e industriales. Las empresas alimentarias se registran ante el servicio de regulación alimentaria de la intendencia. Tasas, plazos y renovación: confirmar en la intendencia y en gub.uy/tramites.$k$,'gub.uy (Trámites); Intendencia de Montevideo; MSP','https://www.gub.uy/tramites/habilitaciones-comerciales-paysandu',$k$Material informativo de fuentes oficiales uruguayas; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.$k$,'es','draft');